function initial(){const defs=[['photos',20,210,100],['window',204,8,105],['books',58,38,0],['bed',88,226,0],['record',281,75,0],['plant',296,273,0],['chair',248,192,0],['box',156,308,0],['network',20,88,123]];state.items=defs.map(([type,x,y,z])=>({id:uid(),type,x,y,z,title:kind(type).name,story:'',files:[],people:[]}))}
function url(file){let u=URL.createObjectURL(file.blob);urls.push(u);return u}
function draw(){for(const item of state.items){if(item.type==='box'&&item.title==='Boxws')item.title='Box';}const oldNames={"digital":["Digital Desk","Digital devices"],"pet":["Pet Cat","Pet"],"network":["Constellation","Relationships"],"box":["Memory Box","Box"],"letter":["Unsent Letter","Letter"]};for(const item of state.items){const rename=oldNames[item.type];if(rename&&item.title===rename[0])item.title=rename[1];}for(const item of state.items){if(item.type==='plant'&&item.title==='Wish Plant')item.title='Plant';}migrateMoodLamps();for(let u of urls)URL.revokeObjectURL(u);urls=[];$('#roomTitle').textContent=document.body.hasAttribute('data-original')&&state.title==='Make room for who you are.'?'Curating your own room':state.title;$('#count').textContent=`${state.items.length} objects`;$('#mood').textContent=document.body.hasAttribute('data-original')?(state.night?'Evening':'Afternoon'):(state.night?'☾ Evening':'☀ Afternoon');$('.room-panel').classList.toggle('night',state.night);let s='';for(let item of [...state.items].sort((a,b)=>(a.x+a.y+a.z*.1)-(b.x+b.y+b.z*.1))){projectionRotation=0;let [x,y]=p(item.x,item.y,item.z);projectionRotation=rotation(item.rotation);let img=item.files.find(f=>/^image\/(png|jpeg|webp|gif|avif|bmp)$/.test(f.blob.type));s+=`<g class="object" data-id="${item.id}" tabindex="0" role="button" aria-label="${esc(item.title)}, click to edit" transform="translate(${450+x} ${347+y})"><title>${esc(item.title)}</title><ellipse class="selection" cy="4" rx="53" ry="23" fill="#a4b18a44" stroke="#7e9361" stroke-width="2" stroke-dasharray="5 4"/>${art(item.type,item.color)}`;if(img&&item.type==='photos')s+=`<image href="${url(img)}" x="-30" y="-68" width="55" height="38" preserveAspectRatio="xMidYMid slice" transform="${screenMatrix(4.62,9.31)}"/>`;if(img&&item.type==='window')s+=`<image href="${url(img)}" x="-37" y="-103" width="74" height="96" preserveAspectRatio="xMidYMid slice" transform="${screenMatrix(8)}"/>`;if(item.type==='tv'){const clip=item.files.find(f=>f.blob.type.startsWith('video/'));if(clip){const frame=tvFrames.get(clip.id);s+=`<image data-tv-file="${esc(clip.id)}" href="${frame||''}" opacity="${frame?1:0}" x="-36" y="-85" width="59" height="41" preserveAspectRatio="xMidYMid slice" transform="${screenMatrix(3)}"/>`;if(!tvFrames.has(clip.id))requestTvFrame(clip);}}if(item.type==='network')s+=roomRelationships(item);if(item.story||item.files.length||item.books?.length||item.people?.length)s+=circle(39,-68,4,'#7f9467')+circle(39,-68,1.6,'#f8f5e9');s+='</g>';projectionRotation=0;}$('#objects').innerHTML=s}
function catalog(){let grid=$('#catalog');grid.innerHTML=kinds.filter(k=>filter==='all'||k.cat===filter).map(k=>`<button class="item-card" data-kind="${k.type}" aria-label="Add ${k.name}"><span class="plus">＋</span>${icon(k.type)}<strong>${k.name}</strong></button>`).join('')}
async function initDb(){return new Promise((resolve,reject)=>{let r=indexedDB.open('a-room-of-my-own',1);r.onupgradeneeded=()=>r.result.createObjectStore('room');r.onerror=()=>reject(r.error);r.onsuccess=()=>resolve(r.result)})}
async function save(){if(!db){$('#saved').textContent='○ Not saved. Please export a backup.';return false}const snapshot=structuredClone(state);return new Promise(resolve=>{let t=db.transaction('room','readwrite');t.objectStore('room').put(snapshot,'current');t.oncomplete=()=>{$('#saved').textContent='● Saved in this browser';resolve(true)};t.onerror=()=>{$('#saved').textContent='○ Save failed. Please export a backup.';toast('Browser storage is full or restricted. Export your room to keep a backup.');resolve(false)}})}
async function load(){try{db=await initDb();const value=await new Promise((res,rej)=>{let r=db.transaction('room').objectStore('room').get('current');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});if(value){state=value;const defaults={"\u628a\u81ea\u5df1，\u6162\u6162\u653e\u8fdb\u6765。":"Make room for who you are.","\u6211\u7684\u79c1\u4eba\u5c55\u89c8":"My private exhibition","\u672a\u5bc4\u51fa\u7684\u4fe1":"Letter","\u672a\u6765\u7684\u661f\u661f":"Future Stars","\u5173\u7cfb\u661f\u56fe":"Relationships","\u613f\u671b\u76c6\u683d":"Plant","\u8bb0\u5fc6\u5730\u56fe":"Memory Map","\u68a6\u4e0e\u4fbf\u7b7e":"Dreams & Notes","\u7167\u7247\u5899":"Photo Wall","\u5531\u7247\u673a":"Record Player","\u8bb0\u5fc6\u76d2":"Box","\u5fc3\u60c5\u7a97":"Mood Window","\u7a7a\u6905\u5b50":"Empty Chair","\u4e66\u67b6":"Bookshelf","\u955c\u5b50":"Mirror","\u8863\u67dc":"Wardrobe"};state.title=defaults[state.title]||state.title;for(const item of state.items){item.title=defaults[item.title]||item.title;if(item.type==='window'&&item.title==='Mood Window')item.title='Window';}}else initial()}catch{initial();toast('Local storage is unavailable. Export your room to keep a backup.');$('#saved').textContent='○ Please export a backup'}architecture();draw();catalog();syncMusic();loadResetBackup();requestAnimationFrame(animatePets)}
function add(type){if(state.items.length>=40){toast('Your room holds up to 40 objects. Leave yourself a little space.');return}let n=state.items.length,item={id:uid(),type,title:kind(type).name,story:'',x:110+(n%4)*43,y:125+(Math.floor(n/4)%4)*40,z:0,files:[],people:[]};if(type==='window'){item.x=110+(n%4)*45;item.y=8;item.z=105;}if(type==='pet'){const spot=findPetSpot(item);item.x=spot.x;item.y=spot.y;}state.items.push(item);draw();save();openEditor(item.id);return item}
function openEditor(id){editing=id;draft=structuredClone(state.items.find(i=>i.id===id));if(!draft)return;$('#itemTitle').closest('label').hidden=draft.type==='moodWindow';let k=kind(draft.type);$('#objectType').textContent='YOUR COLLECTION · '+k.name;$('#objectPreview').innerHTML=icon(draft.type);$('#editorHeading').textContent=k.name;$('#objectPrompt').textContent=k.prompt;$('#objectMeaning').textContent=objectMeanings[draft.type]||'';$('#letterRecipientSection').hidden=draft.type!=='letter';$('#letterRecipient').value=draft.type==='letter'?(draft.recipient||''):'';const isBooks=draft.type==='books';draft.books=Array.isArray(draft.books)?draft.books:[];$('#titleLabel').textContent=isBooks?'The name of the book':draft.type==='box'?"What's inside the box?":draft.type==='stars'?'Your hopes for the future':draft.type==='mirror'?'Who do you see in the mirror?':'Give it a name';$('#storyLabel').textContent=isBooks?'About this book':draft.type==='box'?'Describe a little about it.':'What does it mean to you?';$('#itemTitle').value=isBooks?'':draft.title;$('#itemTitle').required=!isBooks;$('#itemTitle').placeholder=isBooks?'Enter a book title':'';$('#itemStory').value=isBooks?'':draft.story;$('#itemStory').placeholder=isBooks?'Add the author, a favorite passage, or a note about this book.':draft.type==='box'?'An object, an interest, or a moment from your daily life...':'A memory, a person, or a thought you want to keep.';$('#booksSection').hidden=!isBooks;$('#recordSection').hidden=draft.type!=='record';$('#fileInput').accept=draft.type==='record'?'audio/*,video/*':'';$('#editorForm .primary').textContent='Save';$('#legacyShelf').hidden=!isBooks||!draft.story;$('#legacyShelfNotes').textContent=draft.story||'';$('#moodWindowSection').hidden=draft.type!=='moodWindow';if(draft.type==='moodWindow'){draft.color=moodColor(draft.color);$('#moodColor').value=draft.color;$('#moodColorValue').textContent=draft.color;$('#objectPreview').innerHTML=iconMood(draft.color);$('#titleLabel').textContent='Give your mood a name';$('#storyLabel').textContent='Leave a mood note';$('#itemTitle').placeholder='Calm, hopeful, a little cloudy...';$('#itemTitle').required=false;$('#itemStory').placeholder='How are you feeling today? Leave a message for yourself.';$('#editorForm .primary').textContent='Save';}if(draft.type==='window'){ $('#titleLabel').textContent='The name of the place';$('#storyLabel').textContent='Why this place?';$('#itemTitle').placeholder='A city, a favorite place, or a landscape';if(draft.title==='Window'||draft.title==='Mood Window')$('#itemTitle').value='';$('#itemTitle').required=false;$('#itemStory').placeholder='A place you want to visit, somewhere you love, or a view you wish you could wake up to.';$('#fileInput').accept='image/png,image/jpeg,image/webp,image/gif,image/avif,image/bmp';$('#editorForm .primary').textContent='Save';}if(draft.type==='tv'){$('#titleLabel').textContent='The name of the video';$('#storyLabel').textContent='About this video';$('#itemTitle').placeholder='Give your video a title';if(draft.title==='Television')$('#itemTitle').value='';$('#itemTitle').required=false;$('#itemStory').placeholder='What would you like to watch in your room?';$('#fileInput').accept='video/*';$('#editorForm .primary').textContent='Save';}if(draft.type==='pet'){$('#titleLabel').textContent="Your pet's name";$('#storyLabel').textContent='About your pet';$('#itemTitle').placeholder='What is your cat called?';$('#itemStory').placeholder='A little about your companion.';$('#editorForm .primary').textContent='Save';}$('#attach').textContent=draft.type==='window'?'＋ Add scenery photos':draft.type==='tv'?'＋ Upload video':'＋ Add files';$('#fileHelp').textContent=draft.type==='window'?'Add scenery photos. The first photo appears in your window. Up to 20 MB per photo.':draft.type==='tv'?'Upload a video, press Play to preview, then save. Up to 20 MB per video.':draft.type==='record'?'Audio and video files. Up to 20 MB per file.':'Images, audio, video, PDF, and other files. Up to 20 MB per file.';if(draft.type==='kitchen'){$('#titleLabel').textContent='Dish, snack, or kitchen name';$('#storyLabel').textContent='Your story or recipe';$('#itemTitle').placeholder="A recipe, a favourite dish, or snacks";if(draft.title==='Kitchen Shelf')$('#itemTitle').value='';$('#itemTitle').required=false;$('#itemStory').placeholder='Why do you love it? Share a food memory, ingredients, or the steps to make it.';$('#attach').textContent='＋ Add photos, recipes & videos';$('#fileHelp').textContent='Food photos, recipe files, cooking videos, and other keepsakes. Up to 20 MB per file.';$('#editorForm .primary').textContent='Save';}if(draft.type==='digital'){$('#titleLabel').textContent='Name your digital world';$('#storyLabel').textContent='Your digital story';$('#itemTitle').placeholder='My digital world, a favourite game, or a trusted device';if(draft.title==='Digital devices')$('#itemTitle').value='';$('#itemTitle').required=false;$('#itemStory').placeholder='What has this device helped you do? Share what you explore, create, play, or connect with online.';$('#attach').textContent='＋ Add screenshots, creations & files';$('#fileHelp').textContent='Desktop or game screenshots, digital creations, photos, videos, and other files. Up to 20 MB per file.';$('#editorForm .primary').textContent='Save';}if(isBooks)renderBooks();updateMusicControls();$('#peopleSection').hidden=draft.type!=='network';$('#personName').value='';$('#personRelation').value='';renderPeople();renderFiles();updateRotationPreview();$('#editor').showModal()}
function renderBooks(){const wrap=$('#bookList');wrap.replaceChildren();$('#bookCount').textContent='('+draft.books.length+')';if(!draft.books.length){const empty=document.createElement('p');empty.className='field-note';empty.textContent='Your shelf is waiting for its first book.';wrap.append(empty);}for(const [index,book] of draft.books.entries()){const card=document.createElement('article');card.className='book-card';const title=document.createElement('strong');title.textContent=book.title;const notes=document.createElement('p');notes.textContent=book.notes;const remove=document.createElement('button');remove.type='button';remove.className='text-button';remove.textContent='Remove book';remove.setAttribute('aria-label','Remove '+book.title);remove.onclick=()=>{draft.books.splice(index,1);renderBooks()};card.append(title,notes,remove);wrap.append(card)}}
function addBook(){const title=$('#itemTitle').value.trim(),notes=$('#itemStory').value.trim();if(!title){toast('Enter the name of the book first.');$('#itemTitle').focus();return false}if(draft.books.length>=100){toast('This bookshelf holds up to 100 books.');return false}draft.books.push({title,notes});$('#itemTitle').value='';$('#itemStory').value='';renderBooks();return true}
$('#addBook').onclick=addBook;
function renderFiles(){let wrap=$('#attachments');wrap.replaceChildren();$('#fileCount').textContent=draft.files.length?`(${draft.files.length})`:'';for(let f of draft.files){let card=document.createElement('div');card.className='file-card';let type=f.blob.type,u=url(f);if(/^image\/(png|jpeg|webp|gif|avif|bmp)$/.test(type)){let im=document.createElement('img');im.src=u;im.alt=f.name;card.append(im)}else if(type.startsWith('audio/')||type.startsWith('video/')){if(draft.type==='record'){let play=document.createElement('button');play.type='button';play.className='pill';play.textContent='Play in room';play.onclick=()=>playTrack(draft,f,true);card.append(play)}else{let media=document.createElement(type.startsWith('audio/')?'audio':'video');media.src=u;media.controls=true;media.preload='metadata';media.playsInline=true;if(draft.type==='tv'){media.setAttribute('aria-label','Watch '+f.name);media.addEventListener('play',()=>{roomAudio.pause();document.querySelectorAll('#attachments video').forEach(other=>{if(other!==media)other.pause()})});media.addEventListener('error',()=>toast('This video format cannot be played. Try an MP4 or WebM video.'));}card.append(media)}}let row=document.createElement('div');row.className='file-row';let name=document.createElement('span');name.textContent=f.name;let a=document.createElement('a');a.href=u;a.download=f.name;a.textContent='Download';let del=document.createElement('button');del.type='button';del.textContent='×';del.setAttribute('aria-label','Remove file '+f.name);del.onclick=()=>{draft.files=draft.files.filter(x=>x.id!==f.id);if(draft.type==='record'&&music.fileId===f.id){stopMusic();}renderFiles()};row.append(name,a,del);card.append(row);const noteLabel=document.createElement("label");noteLabel.className="file-note-label";noteLabel.textContent="A note for this file";const note=document.createElement("textarea");note.className="file-note-input";note.rows=3;note.maxLength=2000;note.placeholder="A memory, a thought, or a little context…";note.value=f.note||"";note.setAttribute("aria-label","Note for "+f.name);note.oninput=()=>{f.note=note.value.slice(0,2000)};noteLabel.append(note);card.append(noteLabel);const noteHelp=document.createElement("p");noteHelp.className="field-note";noteHelp.textContent="Saved with this file when you save the object.";card.append(noteHelp);wrap.append(card)}}
function constellationMarkup(people=[]){let center=[175,100],s='';for(let [i,who] of people.entries()){let angle=i/Math.max(people.length,1)*Math.PI*2-Math.PI/2,x=175+Math.cos(angle)*122,y=100+Math.sin(angle)*67;const label=String(who.name||'');s+=line(center,[x,y],'#bfc8b0',1.5)+circle(x,y,8,'#aab997')+`<text x="${x}" y="${y+22}" text-anchor="middle" font-size="10" fill="#58644d"${label.length>15?' textLength="92" lengthAdjust="spacingAndGlyphs"':''}><title>${esc(label+(who.relation?' · '+who.relation:''))}</title>${esc(label)}</text>`;}return s+circle(...center,18,'#7c9267')+'<text x="175" y="104" text-anchor="middle" font-size="11" fill="white">Me</text>'}
function roomRelationships(item){return face(-47,6,5,94,72,'#eff1e7')+`<g class="room-constellation" transform="${screenMatrix(7)}"><svg x="-45" y="-75" width="90" height="66" viewBox="0 0 350 200" preserveAspectRatio="xMidYMid meet" overflow="hidden" aria-label="Your constellation">${constellationMarkup(item.people||[])}</svg></g>`}
function renderPeople(){let people=draft.people;$('#network').innerHTML='<svg viewBox="0 0 350 200" role="img" aria-label="Relationships">'+constellationMarkup(people)+'</svg>';$('#peopleList').replaceChildren();for(let [i,who] of people.entries()){let row=document.createElement('div');row.className='person-row';let txt=document.createElement('span');txt.textContent=who.name+(who.relation?' · '+who.relation:'');let b=document.createElement('button');b.type='button';b.textContent='Remove';b.onclick=()=>{draft.people.splice(i,1);renderPeople()};row.append(txt,b);$('#peopleList').append(row)}}
$('#catalog').onclick=e=>{let b=e.target.closest('[data-kind]');if(b)add(b.dataset.kind)};
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{filter=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-selected',String(t===b))});catalog()});
$('#closeEditor').onclick=()=>$('#editor').close();$('#editor').addEventListener('close',()=>{document.querySelectorAll('#attachments audio,#attachments video').forEach(m=>m.pause());editing=null;draft=null;syncMusic();draw()});
$('#editorForm').onsubmit=async e=>{e.preventDefault();if(draft.type==='books'){if(($('#itemTitle').value.trim()||$('#itemStory').value.trim())&&!addBook())return;}else{draft.title=$('#itemTitle').value.trim()||kind(draft.type).name;draft.story=$('#itemStory').value.trim();if(draft.type==='letter')draft.recipient=$('#letterRecipient').value.trim().slice(0,100);}let i=state.items.findIndex(x=>x.id===editing);if(i<0)return;state.items[i]=draft;$('#editor').close();draw();if(await save())toast('A little piece of you, safely kept.')};
$('#remove').onclick=()=>{if(!confirm('Remove this object? Its story and attached files will also be removed.'))return;state.items=state.items.filter(i=>i.id!==editing);$('#editor').close();syncMusic();draw();save();toast('Object removed')};
$('#addPerson').onclick=()=>{let name=$('#personName').value.trim();if(!name){$('#personName').focus();return}if(draft.people.length>=12){toast('This constellation holds up to 12 people.');return}draft.people.push({name,relation:$('#personRelation').value.trim()});$('#personName').value='';$('#personRelation').value='';renderPeople()};
$('#attach').onclick=()=>$('#fileInput').click();
$('#fileInput').onchange=e=>{if(!draft)return;let added=0,firstTrack=null;for(let file of e.target.files){if(draft.type==='tv'&&!file.type.startsWith('video/')){toast(file.name+' is not a video file.');continue}if(draft.type==='window'&&!/^image\/(png|jpeg|webp|gif|avif|bmp)$/.test(file.type)){toast(file.name+' is not a supported scenery photo.');continue}if(draft.type==='record'&&!isTrack({blob:file})){toast(file.name+' is not an audio or video file.');continue}if(file.size>20*1024*1024){toast(file.name+' is over 20 MB and was not added.');continue}if(draft.files.length>=20){toast('You can attach up to 20 files to each object.');break}const attachment={id:uid(),name:file.name,note:"",blob:file};draft.files.push(attachment);if(!firstTrack&&isTrack(attachment))firstTrack=attachment;added++}renderFiles();e.target.value='';if(added){if(draft.type==='record'){const stored=state.items.find(i=>i.id===draft.id);stored.files=structuredClone(draft.files);if(firstTrack){stored.trackId=firstTrack.id;draft.trackId=firstTrack.id;playTrack(draft,firstTrack,true);}save();$('#objectPrompt').textContent=added+' track(s) added. Your room has a soundtrack.';}else $('#objectPrompt').textContent=added+' file(s) added. Save your story below.';}};
document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{let [dx,dy]=b.dataset.move.split(',').map(Number);draft.x=Math.max(20,Math.min(330,draft.x+dx*20));draft.y=Math.max(15,Math.min(330,draft.y+dy*20));toast('Position updated. Save to place it in its new spot.')});
$('#mood').onclick=()=>{state.night=!state.night;draw();save()};$('#rename').onclick=()=>{$('#nameInput').value=state.title==='Make room for who you are.'?'':state.title;$('#nameDialog').showModal()};$('#cancelName').onclick=()=>$('#nameDialog').close();$('#nameForm').onsubmit=e=>{e.preventDefault();state.title=$('#nameInput').value.trim()||'My private exhibition';draw();save();$('#nameDialog').close()};
$('#arrange').onclick=()=>{arranging=!arranging;$('#scene').classList.toggle('arranging',arranging);$('#arrange').textContent=arranging?'✓ Done arranging':'⤧ Arrange room';$('#hint').hidden=!arranging;$('#hint').textContent=arranging?'Drag objects to move them. Click to edit.':''};
$('#objects').addEventListener('keydown',e=>{let el=e.target.closest('[data-id]');if(el&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openObject(el.dataset.id)}});
$('#room').addEventListener('pointerdown',e=>{let el=e.target.closest('[data-id]');if(!el)return;let item=state.items.find(i=>i.id===el.dataset.id);if(!arranging){drag={id:item.id,startX:e.clientX,startY:e.clientY,click:true};return}e.preventDefault();let rect=$('#room').getBoundingClientRect();drag={id:item.id,startX:e.clientX,startY:e.clientY,x:item.x,y:item.y,scale:900/rect.width,moved:false};$('#room').setPointerCapture(e.pointerId)});
$('#room').addEventListener('pointermove',e=>{if(!drag||drag.click)return;let dx=(e.clientX-drag.startX)*drag.scale,dy=(e.clientY-drag.startY)*drag.scale;if(Math.abs(dx)+Math.abs(dy)>5)drag.moved=true;let item=state.items.find(i=>i.id===drag.id);item.x=Math.max(20,Math.min(335,drag.x+dx/1.732+dy));item.y=Math.max(15,Math.min(335,drag.y+dy-dx/1.732));draw()});
$('#room').addEventListener('pointerup',e=>{if(!drag)return;let d=drag;drag=null;if(d.click){if(Math.abs(e.clientX-d.startX)+Math.abs(e.clientY-d.startY)<10)openObject(d.id)}else if(d.moved)save();else openObject(d.id)});$('#room').addEventListener('pointercancel',()=>{drag=null;save()});
function download(blob,name){let u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),60000)}
const toData=blob=>new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(r.error);r.readAsDataURL(blob)});
$('#export').onclick=async()=>{let b=$('#export');b.disabled=true;b.textContent='Packing your room…';try{let data=structuredClone(state);for(let i of data.items)for(let f of i.files){f.data=await toData(f.blob);delete f.blob}download(new Blob([JSON.stringify(data)],{type:'application/json'}),'a-room-of-my-own-backup.json');toast('Your room and files are packed. Keep the downloaded backup safe.')}catch{toast('Export failed. Please try again.')}finally{b.disabled=false;b.textContent='Export room ↗'}};
$('#import').onclick=()=>$('#importInput').click();$('#importInput').onchange=async e=>{let file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>200*1024*1024){toast('This backup is too large. Choose a file under 200 MB.');return}try{let data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.items)||data.items.length>40)throw Error();let items=data.items.map(i=>{if(!kind(i.type)||!Array.isArray(i.files)||i.files.length>20)throw Error();return {id:uid(),type:i.type,title:String(i.title||kind(i.type).name).slice(0,50),story:String(i.story||'').slice(0,4000),recipient:i.type==='letter'?String(i.recipient||'').slice(0,100):'',x:Math.max(15,Math.min(335,Number(i.x)||100)),y:Math.max(15,Math.min(335,Number(i.y)||100)),z:Math.max(0,Math.min(180,Number(i.z)||0)),color:moodColor(i.color),rotation:rotation(i.rotation),books:(Array.isArray(i.books)?i.books:[]).slice(0,100).filter(b=>b&&typeof b.title==='string').map(b=>({title:b.title.slice(0,50),notes:String(b.notes||'').slice(0,4000)})),people:(Array.isArray(i.people)?i.people:[]).slice(0,12).map(p=>({name:String(p.name).slice(0,30),relation:String(p.relation||'').slice(0,40)})),files:i.files.map(f=>{let m=/^data:([^;,]*);base64,([A-Za-z0-9+/=\r\n]*)$/.exec(f.data);if(!m)throw Error();let binary=atob(m[2]);if(binary.length>20*1024*1024)throw Error();let bytes=Uint8Array.from(binary,c=>c.charCodeAt(0));return {id:uid(),name:String(f.name||'file').slice(0,255),note:String(f.note||'').slice(0,2000),blob:new Blob([bytes],{type:m[1]||'application/octet-stream'})}})}});if(!confirm('Importing replaces your current room. Have you exported anything you want to keep?'))return;state={version:1,title:String(data.title||'My private exhibition').slice(0,32),night:!!data.night,items};stopMusic();syncMusic();draw();if(await save())toast('Welcome back to your room.')}catch{toast('Unable to read this backup. Choose a room file exported from this website.')}};
// Room playback has its own media element and URL; editing and redrawing cannot interrupt it.
const roomAudio=$('#roomAudio');
const music={itemId:null,fileId:null,url:null,generation:0,status:'',volume:0.6};
function isTrack(file){return /^(audio|video)\//.test(file.blob.type)}
function updateMusicControls(){document.querySelectorAll('.music-toggle').forEach(b=>{b.textContent=roomAudio.paused?'Play':'Pause';b.disabled=!music.url;b.setAttribute('aria-label',roomAudio.paused?'Play room music':'Pause room music')});document.querySelectorAll('.music-next').forEach(b=>b.disabled=!music.url);document.querySelectorAll('.music-volume').forEach(input=>input.value=String(music.volume));document.querySelectorAll('.music-status').forEach(el=>el.textContent=music.status);$('#musicDock').hidden=!music.url;}
function stopMusic(){music.generation++;roomAudio.pause();roomAudio.removeAttribute('src');roomAudio.load();if(music.url)URL.revokeObjectURL(music.url);music.url=null;music.itemId=null;music.fileId=null;music.status='';updateMusicControls()}
async function resumeMusic(){const generation=music.generation;try{await roomAudio.play();if(generation!==music.generation)return;music.status='Playing in your room';}catch(error){if(generation!==music.generation)return;music.status=error.name==='NotAllowedError'?'Click Play to start the sound.':'This file cannot be played. Try MP3, WAV, or MP4.';}updateMusicControls()}
function playTrack(item,file,autoplay){if(!isTrack(file))return;if(music.itemId!==item.id||music.fileId!==file.id){stopMusic();music.itemId=item.id;music.fileId=file.id;music.url=URL.createObjectURL(file.blob);roomAudio.src=music.url;roomAudio.volume=music.volume;$('#trackName').textContent=file.name;music.status='Ready to play';}updateMusicControls();if(autoplay)resumeMusic()}
function syncMusic(){if(music.url){const existing=state.items.find(i=>i.id===music.itemId);if(existing?.files.some(f=>f.id===music.fileId))return;stopMusic()}const item=state.items.find(i=>i.type==='record'&&i.files.some(isTrack));if(item){const file=item.files.find(f=>f.id===item.trackId&&isTrack(f))||item.files.find(isTrack);playTrack(item,file,false)}}
function nextTrack(){const item=(draft?.id===music.itemId?draft:null)||state.items.find(i=>i.id===music.itemId);if(!item)return;const tracks=item.files.filter(isTrack);if(!tracks.length){stopMusic();return}const index=tracks.findIndex(f=>f.id===music.fileId);const next=tracks[(index+1)%tracks.length];if(next.id===music.fileId)roomAudio.currentTime=0;playTrack(item,next,true)}
roomAudio.addEventListener('ended',nextTrack);roomAudio.addEventListener('play',()=>{music.status='Playing in your room';updateMusicControls()});roomAudio.addEventListener('pause',()=>{if(music.url)music.status='Paused';updateMusicControls()});roomAudio.addEventListener('error',()=>{if(music.url){music.status='This file cannot be played. Try another audio or video format.';updateMusicControls()}});
document.querySelectorAll('.music-toggle').forEach(b=>b.onclick=()=>{if(roomAudio.paused)resumeMusic();else roomAudio.pause()});document.querySelectorAll('.music-next').forEach(b=>b.onclick=nextTrack);document.querySelectorAll('.music-volume').forEach(input=>input.oninput=()=>{music.volume=Number(input.value);roomAudio.volume=music.volume;updateMusicControls()});$('#musicStop').onclick=()=>{roomAudio.pause();roomAudio.currentTime=0;music.status='Stopped';updateMusicControls()};

function iconMood(color){return '<svg viewBox="-105 -150 210 180" aria-hidden="true">'+art('moodWindow',color)+'</svg>'}
$('#moodColor').oninput=()=>{if(draft?.type!=='moodWindow')return;draft.color=moodColor($('#moodColor').value);$('#moodColorValue').textContent=draft.color;updateRotationPreview()};
// Generate a still from the original video without starting audible playback.
const tvFrames=new Map();
function requestTvFrame(file){tvFrames.set(file.id,null);captureVideoFrame(file.blob).then(frame=>{tvFrames.set(file.id,frame);if(frame)document.querySelectorAll('[data-tv-file]').forEach(image=>{if(image.getAttribute('data-tv-file')===file.id){image.setAttribute('href',frame);image.setAttribute('opacity','1')}})})}
function captureVideoFrame(blob){return new Promise(resolve=>{const video=document.createElement('video'),source=URL.createObjectURL(blob);let finished=false,target=0;const timer=setTimeout(()=>finish(null),12000);function finish(value){if(finished)return;finished=true;clearTimeout(timer);video.onloadedmetadata=null;video.onloadeddata=null;video.onseeked=null;video.onerror=null;video.pause();video.removeAttribute('src');video.load();URL.revokeObjectURL(source);resolve(value)}function capture(){if(finished||video.readyState<2||video.seeking)return;try{if(!video.videoWidth||!video.videoHeight){finish(null);return}const canvas=document.createElement('canvas');canvas.width=480;canvas.height=Math.max(1,Math.round(480*video.videoHeight/video.videoWidth));const context=canvas.getContext('2d');if(!context){finish(null);return}context.drawImage(video,0,0,canvas.width,canvas.height);finish(canvas.toDataURL('image/jpeg',0.8))}catch{finish(null)}}video.muted=true;video.playsInline=true;video.preload='auto';video.onloadedmetadata=()=>{target=Number.isFinite(video.duration)&&video.duration>0?Math.min(.5,video.duration/4):0;if(target>0){try{video.currentTime=target}catch{capture()}}else capture()};video.onloadeddata=()=>{if(target===0)capture()};video.onseeked=capture;video.onerror=()=>finish(null);video.src=source;video.load()})}

function updateRotationPreview(){draft.rotation=rotation(draft.rotation);$('#rotationValue').textContent=draft.rotation+'°';$('#objectPreview').innerHTML=icon(draft.type,draft.color,draft.rotation)}
function rotateDraft(amount){if(!draft)return;draft.rotation=rotation((draft.rotation||0)+amount);updateRotationPreview()}
$('#rotateLeft').onclick=()=>rotateDraft(-90);$('#rotateRight').onclick=()=>rotateDraft(90);

// Pet movement updates only its SVG group; uploaded media URLs stay untouched.
const petMotion=new Map();let lastPetFrame=0,petFrameBudget=0;
function petArt(resting=false,direction=1){return '<g class="pet-art '+(resting?'pet-resting':'pet-awake')+'" transform="scale('+direction+' 1)">'+
 '<ellipse cx="0" cy="2" rx="27" ry="10" fill="#77674e" opacity=".17"/>'+
 '<g class="pet-body"><path d="M-17 -17 Q-39 -30 -33 -40 Q-26 -45 -27 -34" fill="none" stroke="#bf916d" stroke-width="7" stroke-linecap="round"/>'+
 (resting?'<ellipse cx="-2" cy="-10" rx="24" ry="13" fill="#d7b18b"/><path d="M-20 -9 Q-16 7 8 -3" fill="none" stroke="#bf916d" stroke-width="7" stroke-linecap="round"/>':'<g class="pet-legs"><path d="M-14 -16 L-14 0 M14 -16 L14 0" stroke="#b78b67" stroke-width="7" stroke-linecap="round"/></g><ellipse cx="-1" cy="-20" rx="23" ry="14" fill="#d7b18b"/><path d="M-12 -30 l-2 8 M-2 -33 l-1 9" stroke="#b88a65" stroke-width="3" stroke-linecap="round"/>')+
 '<g transform="translate(20 '+(resting?-12:-30)+')"><path d="M-12 -4 L-13 -20 L-3 -13 L6 -13 L15 -19 L14 -2 Z" fill="#d7b18b"/><path d="M-9 -10 L-10 -16 L-5 -12 M9 -11 L12 -16 L12 -8" fill="#d6a39a"/><ellipse cy="-2" rx="15" ry="12" fill="#dfbb96"/><ellipse cx="5" cy="3" rx="8" ry="5" fill="#efe1c5"/>'+
 (resting?'<path d="M-7 -3 q3 3 6 0 M7 -3 q3 3 6 0" fill="none" stroke="#665a49" stroke-width="1.5"/>':'<circle cx="-3" cy="-4" r="1.7" fill="#514c40"/><circle cx="10" cy="-4" r="1.7" fill="#514c40"/>')+
 '<path d="M2 1 L6 1 L4 4Z" fill="#ac7e71"/><path d="M-7 3 l-10 -2 M-7 6 l-10 2 M11 4 l10 -1" stroke="#8f806a" stroke-width=".8"/></g></g>'+
 (resting?'<text x="25" y="-40" fill="#8a967b" font-size="10" font-family="serif">z z</text>':'')+'</g>'}
const petFootprints={digital:[55,34],kitchen:[42,27],moodWindow:[23,18],bed:[51,76],books:[43,23],wardrobe:[46,30],record:[48,35],chair:[32,30],box:[37,28],letter:[38,29],tv:[54,29],plant:[23,23],mirror:[30,22],stars:[27,18]};
function petSpotFree(x,y,pet){if(x<27||x>330||y<27||y>330)return false;return !state.items.some(other=>{if(other.id===pet.id||other.z>10)return false;let size=petFootprints[other.type];if(!size)return false;let [w,h]=size;if(rotation(other.rotation)%180)[w,h]=[h,w];return Math.abs(x-other.x)<w+16&&Math.abs(y-other.y)<h+16})}
function findPetSpot(pet){if(petSpotFree(pet.x,pet.y,pet))return {x:pet.x,y:pet.y};let spots=[];for(let x=30;x<=330;x+=25)for(let y=30;y<=330;y+=25)if(petSpotFree(x,y,pet))spots.push({x,y});spots.sort((a,b)=>Math.hypot(a.x-pet.x,a.y-pet.y)-Math.hypot(b.x-pet.x,b.y-pet.y));return spots[0]||{x:pet.x,y:pet.y}}
function petPathFree(pet,x,y){for(let i=1;i<=12;i++)if(!petSpotFree(pet.x+(x-pet.x)*i/12,pet.y+(y-pet.y)*i/12,pet))return false;return true}
function stepPet(pet,motion,dt){motion.wait-=dt;if(motion.mode==='rest'){if(motion.wait>0)return;for(let i=0;i<30;i++){const angle=Math.random()*Math.PI*2,distance=35+Math.random()*65,x=pet.x+Math.cos(angle)*distance,y=pet.y+Math.sin(angle)*distance;if(petPathFree(pet,x,y)){motion.target={x,y};motion.mode='walk';motion.direction=x-y>pet.x-pet.y?1:-1;return}}motion.wait=3;return}
 const dx=motion.target.x-pet.x,dy=motion.target.y-pet.y,distance=Math.hypot(dx,dy),step=Math.min(distance,18*dt);if(distance<1||!petPathFree(pet,motion.target.x,motion.target.y)){motion.mode='rest';motion.wait=4+Math.random()*8;return}pet.x+=dx/distance*step;pet.y+=dy/distance*step;
}
function animatePets(now){const dt=lastPetFrame?Math.min((now-lastPetFrame)/1000,.15):0;lastPetFrame=now;petFrameBudget+=dt;if(petFrameBudget>=.05){const elapsed=petFrameBudget;petFrameBudget=0;const paused=arranging||!!editing||!!drag||document.hidden||globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches;const nodes=Array.from(document.querySelectorAll('#objects > [data-id]'));for(const id of petMotion.keys())if(!state.items.some(i=>i.id===id))petMotion.delete(id);for(const pet of state.items.filter(i=>i.type==='pet')){let motion=petMotion.get(pet.id);if(!motion){motion={mode:'rest',wait:2+Math.random()*3,direction:1};petMotion.set(pet.id,motion)}if(!paused)stepPet(pet,motion,elapsed);const node=nodes.find(n=>n.dataset.id===pet.id);if(!node)continue;const resting=paused||motion.mode==='rest',direction=paused?(rotation(pet.rotation)%180?-1:1):motion.direction;const pose=String(resting)+direction;let visual=node.querySelector('.pet-art');if(visual&&visual.getAttribute('data-pose')!==pose){visual.outerHTML=petArt(resting,direction);visual=node.querySelector('.pet-art');visual.setAttribute('data-pose',pose)}node.classList.toggle('pet-walking',!resting);node.setAttribute('transform','translate('+(450+(pet.x-pet.y)*.866)+' '+(347+(pet.x+pet.y)*.5-pet.z)+')');}
 if(!paused&&state.items.some(i=>i.type==='pet')){const byId=new Map(state.items.map(i=>[i.id,i]));nodes.sort((a,b)=>{const x=byId.get(a.dataset.id),y=byId.get(b.dataset.id);return (x.x+x.y+x.z*.1)-(y.x+y.y+y.z*.1)});const parent=$('#objects');nodes.forEach((node,index)=>{if(parent.children[index]!==node)parent.insertBefore(node,parent.children[index]||null)})}}
 requestAnimationFrame(animatePets);
}


let resetBackup=null;
function resetRecord(value){if(!db)return Promise.resolve(true);return new Promise(resolve=>{const tx=db.transaction('room','readwrite');tx.objectStore('room').put(value,'beforeReset');tx.oncomplete=()=>resolve(true);tx.onerror=()=>resolve(false)})}
async function loadResetBackup(){if(!db)return;try{const saved=await new Promise((resolve,reject)=>{const req=db.transaction('room').objectStore('room').get('beforeReset');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});if(saved?.version===1&&Array.isArray(saved.items)){resetBackup=saved;$('#undoReset').hidden=false}}catch{}}
function refreshRoom(){stopMusic();petMotion.clear();drag=null;arranging=false;$('#scene').classList.remove('arranging');$('#arrange').textContent='⤧ Arrange room';$('#hint').hidden=true;$('#hint').textContent='';projectionRotation=0;architecture();draw();syncMusic()}
$('#resetRoom').onclick=async()=>{const button=$('#resetRoom');button.disabled=true;try{const backup=structuredClone(state);if(!await resetRecord(backup)){toast('Unable to keep a backup. Export your room before trying again.');return}resetBackup=backup;state={version:1,title:'Make room for who you are.',night:false,items:[]};initial();refreshRoom();$('#undoReset').hidden=false;await save();toast('Room reset. Use Undo reset to bring back your previous room.')}finally{button.disabled=false}};
$('#undoReset').onclick=async()=>{if(!resetBackup)return;state=structuredClone(resetBackup);refreshRoom();if(await save()){resetBackup=null;await resetRecord(null);$('#undoReset').hidden=true}toast('Your previous room is back.')};

